from .tariffs import FIXED_MONTHLY_CHARGE, TIERS


def energy_charge(kwh: float) -> float:
    """Cost of `kWh` under the graduated tiers in tariffs.TIERS."""
    if kwh < 0:
        raise ValueError("kwh must be >= 0")
    total = 0.0
    remaining = kwh
    prev_limit = 0
    for limit, rate in TIERS:
        if remaining <= 0:
            break
        tier_size = limit - prev_limit if limit != float("inf") else remaining
        charge_from_tier = min(remaining, tier_size) * rate
        total += charge_from_tier
        remaining -= min(remaining, tier_size)
        prev_limit = limit
    return total


def monthly_bill(kwh: float) -> float:
    return round(FIXED_MONTHLY_CHARGE + energy_charge(kwh), 2)
